ValidationRule.errorConditionFormula:
AND(
  /* BYPASS por ventana de gracia: solo valida si NO hay gracia activa */
  OR(
    ISBLANK(Validation_Bypass__c),
    NOW() > Validation_Bypass__c
  ),

  /* Contexto: Prospecto o conversión (IsConverted cambió a TRUE) */
  OR(
    ISPICKVAL(Status, "Prospecto"),
    AND(ISCHANGED(IsConverted), IsConverted = TRUE)
  ),

  /* EXCEPCIÓN: familias Usados */
  NOT(
    OR(
      UPPER(TRIM(TEXT(Family__c))) = "AUTOMOVILES USADOS",
      UPPER(TRIM(TEXT(Family__c))) = "VEHICULOS COMERCIALES USADOS"
    )
  ),

  /* Segmento y Modelo: no vacío, no “otro/otros” */
  OR(
    ISBLANK(TEXT(Segmento__c)),
    TEXT(Segmento__c) = "--None--",
    LOWER(TRIM(TEXT(Segmento__c))) = "otro",
    LOWER(TRIM(TEXT(Segmento__c))) = "otros",

    ISBLANK(TEXT(interest_model__c)),
    TEXT(interest_model__c) = "--None--",
    LOWER(TRIM(TEXT(interest_model__c))) = "otro",
    LOWER(TRIM(TEXT(interest_model__c))) = "otros"
  )
)
